//! The syntax-coverage files: sources, catalogue, obligations, cases, receipts and reviews.

use std::collections::BTreeMap;

use serde::{Deserialize, Serialize};
use serde_json::Value;

/// `sources.toml`, generated by the catalogue owner's build.
#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct SourcesFile {
    #[serde(default, rename = "source")]
    pub sources: Vec<Source>,
}

/// One documentation page, pinned by the hashes of what was fetched; the page stays private.
#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Source {
    /// `doc.<page-slug>`.
    pub id: String,
    pub url: String,
    pub title: String,
    /// Empty only for an out-of-scope page.
    pub family: String,
    /// `YYYY-MM-DDTHH:MM:SSZ`.
    pub retrieved_utc: String,
    /// SHA-256 of the fetched page.
    pub page_sha256: String,
    /// SHA-256 of its syntax blocks.
    pub syntax_sha256: String,
    pub syntax_blocks: u32,
    pub status: SourceStatus,
    /// The extraction rules that changed this page's form count.
    pub decisions: Vec<String>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum SourceStatus {
    Forms,
    /// Its grammar is fully covered by a form elsewhere that lists it in `also_sources`.
    Restated,
    NoSyntaxBlock,
    OutOfScope,
}

/// `indexes.toml`: the documentation indexes the page list was read from.
#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct IndexesFile {
    #[serde(default, rename = "index")]
    pub indexes: Vec<Index>,
}

#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Index {
    pub name: String,
    pub sha256: String,
}

/// `aliases.toml`: renamed form ids; an old id is never reused.
#[derive(Clone, Debug, Default, PartialEq, Eq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct AliasesFile {
    #[serde(default, rename = "alias")]
    pub aliases: Vec<Alias>,
}

#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Alias {
    pub from: String,
    /// One id for a rename, several for a split; the old id stays as `absent_from_source`.
    pub to: Vec<String>,
    pub reason: String,
}

/// `catalogue/<family>.toml`.
#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct CatalogueFile {
    #[serde(default, rename = "form")]
    pub forms: Vec<Form>,
    #[serde(default, rename = "definition")]
    pub definitions: Vec<Definition>,
}

/// One documented syntax block or variant; its options and alternatives are obligations.
#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Form {
    /// `sf.<family>.<page-slug>[.<variant>…]`.
    pub id: String,
    pub family: String,
    /// A source id.
    pub source: String,
    /// Other pages restating the same grammar, sorted; the form still counts once, under `source`.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub also_sources: Vec<String>,
    /// The heading on the page.
    pub anchor: String,
    pub kind: FormKind,
    /// Our normalized productions; empty only for a prose form.
    pub grammar: Vec<String>,
    /// SHA-256 of the productions joined by `" || "`, or `prose:<heading>` for a prose form.
    pub grammar_sha256: String,
    /// Names of the page's definitions it uses.
    pub uses: Vec<String>,
    pub status: FormStatus,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum FormKind {
    Statement,
    Call,
    Special,
    Prose,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum FormStatus {
    Catalogued,
    /// Its grammar no longer appears on the page; the id is kept and never reused.
    AbsentFromSource,
}

/// A page's `name ::= …` sub-grammar.
#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Definition {
    /// `<source>::<name>`.
    pub id: String,
    pub source: String,
    pub name: String,
    pub grammar: String,
}

/// `obligations/<family>.toml`.
#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct ObligationsFile {
    #[serde(default, rename = "obligation")]
    pub obligations: Vec<Obligation>,
}

/// One thing a form must be shown to do, `<form>.o<NNN>`.
#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Obligation {
    pub id: String,
    pub kind: ObligationKind,
    pub required: bool,
    /// The alternative, option or placeholder of the grammar it is about.
    #[serde(default)]
    pub target: Option<String>,
    /// For `nesting_depth`: the depths cases must reach.
    #[serde(default)]
    pub depths: Vec<u32>,
    /// For `interaction`: the two co-occurring options or alternatives.
    #[serde(default)]
    pub pair: Vec<String>,
    /// For limits documented only in prose.
    #[serde(default)]
    pub anchor: Option<String>,
    #[serde(default)]
    pub note: Option<String>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Deserialize, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum ObligationKind {
    Alternative,
    OptionPresent,
    OptionAbsent,
    RequiredOperandMissing,
    OperandTypeClass,
    Positive,
    NegativeNeighbour,
    BoundaryBelow,
    BoundaryAt,
    BoundaryAbove,
    IdentifierClass,
    NestingDepth,
    /// Two options or alternatives whose combination the usage notes constrain.
    Interaction,
    /// One case using every independent option of the form together.
    InteractionAllOptions,
    /// A size or nesting value with no documented bound (decision D90).
    Extreme,
}

/// One line of `cases/<family>.jsonl`.
#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Case {
    /// Unique across every family; receipts join on it.
    pub case_id: String,
    pub obligations: Vec<String>,
    pub sql: String,
    pub sql_sha256: String,
    pub setup: Vec<String>,
    /// SHA-256 of `setup` as compact JSON.
    pub setup_sha256: String,
    pub session: BTreeMap<String, Value>,
    /// SHA-256 of `session` as compact JSON with sorted keys.
    pub session_sha256: String,
    pub capture: CaptureMethod,
    /// What Snowflake must do with the SQL for the case to count as evidence.
    #[serde(default)]
    pub expect: Option<Expect>,
    /// For an accepted case expected to fail later, where; informational, never compared.
    #[serde(default)]
    pub stage: Option<Stage>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum Expect {
    /// No syntax error: accepted, or refused after parsing.
    Accept,
    /// A syntax error.
    Reject,
    /// An extreme case Snowflake has not answered yet; never satisfied (decision D90).
    Observe,
    /// An extreme case Snowflake refused: any clean local verdict passes (decision D92).
    Terminates,
}

/// Where an accepted case is expected to fail after parsing.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum Stage {
    /// Any error after parsing.
    Error,
    /// Semantic analysis or later.
    Semantic,
    /// Execution only.
    Runtime,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum CaptureMethod {
    Execute,
    CompileOnlyExplain,
    ExecuteCanonicalRecorder,
    Describe,
    /// DDL executed inside a database the run creates and drops.
    ExecuteDdlInRunDatabase,
}

/// One line of `receipts/*.jsonl`, as the evidence owner's importer writes it.
#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Receipt {
    /// Always `RECEIPT_FORMAT`.
    pub format: String,
    pub case_id: String,
    pub sql_sha256: String,
    pub setup_sha256: String,
    pub session_sha256: String,
    pub session_parameters: BTreeMap<String, Value>,
    pub capture_method: CaptureMethod,
    pub run_id: String,
    /// Canonical runs keep only `query_id_sha256`; a receipt with neither is inadmissible.
    #[serde(default)]
    pub query_id: Option<String>,
    #[serde(default)]
    pub query_id_sha256: Option<String>,
    pub warehouse_version: String,
    /// RFC 3339 in UTC.
    pub recorded_at: String,
    pub outcome: String,
    #[serde(default)]
    pub errno: Option<i64>,
    #[serde(default)]
    pub sqlstate: Option<String>,
    pub phase: Phase,
    /// Why the importer chose the phase.
    pub phase_basis: String,
    /// SHA-256 of the private raw connector record.
    pub raw_record_sha256: String,
    /// SHA-256 of the private run audit.
    pub run_audit_sha256: String,
    /// SHA-256 of the packet the case was submitted in.
    pub packet_sha256: String,
    #[serde(default)]
    pub case_hash: Option<String>,
    #[serde(default)]
    pub input_sha256: Option<String>,
    #[serde(default)]
    pub statement_index: Option<u32>,
    #[serde(default)]
    pub statements_in_input: Option<u32>,
    #[serde(default)]
    pub statements_in_request: Option<u32>,
    /// Statements of the request that completed before it stopped.
    #[serde(default)]
    pub completed_statements: Option<u32>,
    #[serde(default)]
    pub after_sql: Option<String>,
    #[serde(default)]
    pub category: Option<String>,
    /// Why Snowflake refused a statement it parsed; only on a phase after parsing.
    #[serde(default)]
    pub reason_category: Option<ReasonCategory>,
    /// What the importer read the reason category from, such as the error number.
    #[serde(default)]
    pub reason_category_basis: Option<String>,
    /// SHA-256 of the published receipt line this one replaces, for the same case.
    #[serde(default)]
    pub supersedes_receipt_sha256: Option<String>,
    /// A measure other than syntax the receipt was recorded for; never syntax evidence.
    #[serde(default)]
    pub measure: Option<String>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum ReasonCategory {
    MissingObject,
    InvalidOptionOrValue,
    Type,
    Other,
}

/// Where Snowflake stopped, if anywhere.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum Phase {
    Accepted,
    SyntaxError,
    SemanticError,
    RuntimeError,
    UnsupportedFeature,
}

/// `reviews/*.toml`.
#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct ReviewsFile {
    #[serde(default, rename = "review")]
    pub reviews: Vec<Review>,
}

/// One review of a family's catalogue and obligations against one parser source tree.
#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Review {
    pub id: String,
    pub reviewer_lane: Lane,
    /// Empty for a review of page exclusions only.
    pub family: String,
    /// A family review binds its catalogue and obligation files.
    #[serde(default)]
    pub catalogue_sha256: Option<String>,
    #[serde(default)]
    pub obligations_sha256: Option<String>,
    /// A page review binds `sources.toml`.
    #[serde(default)]
    pub sources_sha256: Option<String>,
    /// The full Git tree id of the reviewed parser source; optional on a page review only.
    #[serde(default)]
    pub parser_tree: Option<String>,
    pub reviewed_utc: String,
    pub verdict: ReviewVerdict,
    /// The forms of the family this review verifies; none for the whole family. Never empty.
    #[serde(default)]
    pub forms: Option<Vec<String>>,
    /// Form ids this review accepts as excluded, each with its reason.
    #[serde(default, rename = "exclusion")]
    pub exclusions: Vec<Exclusion>,
    /// Each listed form's fingerprint when reviewed; while it matches, the parser tree may change.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub fingerprints: BTreeMap<String, String>,
    #[serde(default)]
    pub note: Option<String>,
}

#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Exclusion {
    /// Exactly one of a form id and a source id.
    #[serde(default)]
    pub form: Option<String>,
    #[serde(default)]
    pub source: Option<String>,
    pub reason: String,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum Lane {
    A,
    B,
    C,
    Backend,
    /// The omission auditor (decision D88).
    Auditor,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum ReviewVerdict {
    Approved,
    ChangesRequested,
}

/// `unobservable/<family>.toml`.
#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct UnobservableFile {
    #[serde(default, rename = "unobservable")]
    pub entries: Vec<Unobservable>,
    #[serde(default, rename = "diagnostic")]
    pub diagnostics: Vec<Diagnostic>,
}

/// An obligation Snowflake answers only with an internal error; never verified (decision D87).
#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Unobservable {
    pub obligation: String,
    pub form: String,
    pub construct: String,
    pub reason: String,
    /// The captured cases, kept in the cases file without a receipt.
    pub cases: Vec<UnobservableCase>,
    /// The capture, re-run and probe runs; none of them imported.
    pub runs: Vec<String>,
    pub probes: Vec<UnobservableProbe>,
}

/// A 603 record on a construct no obligation requires any more; listed, never scored.
#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Diagnostic {
    pub obligation: String,
    pub form: String,
    pub construct: String,
    pub reason: String,
    /// Retired cases, never resolved against the cases file.
    pub captured: Vec<UnobservableCase>,
    pub runs: Vec<String>,
    pub probes: Vec<UnobservableProbe>,
}

#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct UnobservableCase {
    pub case_id: String,
    pub sql_sha256: String,
}

/// A diagnostic probe; never syntax evidence.
#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct UnobservableProbe {
    pub probe: String,
    pub sql_sha256: String,
    pub result: String,
}

/// Every syntax-coverage file, loaded and format-checked.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SyntaxCoverage {
    pub sources: Vec<Source>,
    pub indexes: Vec<Index>,
    pub aliases: Vec<Alias>,
    /// Family to its forms.
    pub catalogue: BTreeMap<String, Vec<Form>>,
    pub definitions: BTreeMap<String, Vec<Definition>>,
    pub obligations: BTreeMap<String, Vec<Obligation>>,
    pub cases: BTreeMap<String, Vec<Case>>,
    /// Current receipts: none superseded by a later receipt or withdrawn by a run report.
    pub receipts: Vec<Receipt>,
    /// SHA-256 of each published receipt line that is superseded or withdrawn.
    pub retired_receipts: Vec<String>,
    pub reviews: Vec<Review>,
    pub unobservable: Vec<Unobservable>,
    pub diagnostics: Vec<Diagnostic>,
    /// SHA-256 of the sources, aliases, catalogue and obligation files, by relative path.
    pub file_hashes: BTreeMap<String, String>,
}
